{
  "title": "Discussion about living and working abroad",
  "topics": [
    {
      "id": "abroad-living",
      "title": "Living abroad experiences",
      "claims": [
        {
          "text": "P1 asks if anyone lives in Bratislava or elsewhere in Slovakia and who has moved abroad",
          "evidence": [1]
        },
        {
          "text": "P2 mentions knowing only @AndriiRaccoon in Austria and walternet134 in Poland as locals abroad",
          "evidence": [3]
        },
        {
          "text": "P3 says they have at least two acquaintances in Austria, one recently arrived and another for several years",
          "evidence": [12, 13]
        },
        {
          "text": "P1 states they have been in Slovakia for almost a year and do not know the language",
          "evidence": [43]
        },
        {
          "text": "P3 notes they have been living in Austria since 17.11.2025",
          "evidence": [49, 54]
        },
        {
          "text": "P3 lives with a partner who has lived in Austria over 10 years and is pessimistic about the country's future",
          "evidence": [60]
        }
      ]
    },
    {
      "id": "job-search",
      "title": "Finding jobs abroad",
      "claims": [
        {
          "text": "P1 asks how to find a job abroad and whether it is hard",
          "evidence": [16]
        },
        {
          "text": "P3 says it was hard but they managed within two months",
          "evidence": [17]
        },
        {
          "text": "P3 recommends searching on LinkedIn",
          "evidence": [18]
        },
        {
          "text": "P3 reports sending about 100 applications and getting only 3 interviews",
          "evidence": [21]
        },
        {
          "text": "P3 notes many job postings require local language proficiency, about 95% of vacancies",
          "evidence": [26]
        },
        {
          "text": "P3 mentions applying to any position that did not explicitly require German, even outside their tech stack",
          "evidence": [36]
        },
        {
          "text": "P3 says salary on their position was higher but they accepted the minimum because they needed work",
          "evidence": [37]
        }
      ]
    },
    {
      "id": "language-requirements",
      "title": "Language expectations for work and daily life",
      "claims": [
        {
          "text": "P1 asks which language is spoken in Austria, assuming German",
          "evidence": [14]
        },
        {
          "text": "P3 replies that German is used but communication with them is in English",
          "evidence": [15]
        },
        {
          "text": "P3 states most job ads request B2 level language, sometimes B1, and certificates are rarely required",
          "evidence": [46]
        },
        {
          "text": "P3 shares personal difficulty with language barrier in everyday situations and feeling like a migrant when asked to speak English",
          "evidence": [47]
        },
        {
          "text": "P1 mentions language barrier at an anime festival and feeling insecure outside work",
          "evidence": [50, 51, 52]
        }
      ]
    },
    {
      "id": "salary-expectations",
      "title": "Salary expectations abroad",
      "claims": [
        {
          "text": "P1 asks about typical salary and whether P3 applied for a junior position",
          "evidence": [34]
        },
        {
          "text": "P3 believes salaries in Europe are higher than in Ukraine but few notice it",
          "evidence": [35]
        },
        {
          "text": "P3 says their salary was higher than a minimum but still low compared to other jobs like McDonald's",
          "evidence": [37]
        }
      ]
    },
    {
      "id": "event-suggestion",
      "title": "Tech event recommendation",
      "claims": [
        {
          "text": "P3 suggests attending a tech event in Warsaw (wawtech.io/summer)",
          "evidence": [59]
        }
      ]
    }
  ],
  "decisions": [],
  "openQuestions": [
    {
      "text": "P1 asks if P3 personally feels they should stay in Austria",
      "evidence": [58]
    }
  ]
}
